def count_subarrays(nums, k):
    frequencies = {}
    prefix = answer = 0
    for value in nums:
        prefix += value
        answer += frequencies.get(prefix - k, 0)
        frequencies[prefix] = frequencies.get(prefix, 0) + 1
    return answer

