def bfs(graph, start):
    from collections import deque
    queue, seen, order = deque([start]), set(), []
    while queue:
        node = queue.popleft()
        seen.add(node)
        order.append(node)
        for neighbor in graph[node]:
            if neighbor not in seen:
                queue.append(neighbor)
    return order

